style.css:
@-moz-document domain("google.com"), domain("www.google.com") {
/* ? Fundo */
  body {
    background: url(https://i.pinimg.com/736x/eb/8b/ba/eb8bbaf142f1f55dcfe42d73e2e65fe8.jpg) no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* ? Caixa de pesquisa (glass suave pastel) */
  textarea, input {
    background: rgba(255, 245, 220, 0.18) !important; /* tom quentinho */
    backdrop-filter: blur(16px) !important;
    -webkit-backdrop-filter: blur(16px) !important;
    border-radius: 30px !important;
    border: 1px solid rgba(255, 255, 255, 0.5) !important;
    box-shadow: 0 6px 25px rgba(0,0,0,0.12) !important;
    padding: 12px !important;
    color: #ffffff !important;
  }

  /* ? Botões */
  input[type="submit"] {
    background: rgba(200, 255, 230, 0.15) !important; /* verde pastel */
    backdrop-filter: blur(10px) !important;
    border-radius: 20px !important;
    border: 1px solid rgba(255,255,255,0.35) !important;
    color: white !important;
  }

  /* ? Parte de baixo / atalhos */
  .UUbT9, .k1zIA, .FPdoLc {
    background: rgba(255, 240, 200, 0.12) !important;
    backdrop-filter: blur(14px) !important;
    border-radius: 20px !important;
    border: 1px solid rgba(255,255,255,0.3) !important;
  }

  /* ✨ Texto mais suave */
  body, span, div {
    color: rgba(255, 255, 255, 0.9) !important;
  }
}
